'use strict';
const pages={overview:'Treasury overview',new:'Initiate payment',journey:'Payment journey',blockchain:'Blockchain evidence',ledger:'Financial ledger',reconciliation:'Reconciliation',agent:'Investigation agent',platform:'Platform architecture'};
const steps=[
 ['Customer initiates a USD payment','Bank/platform accepts the instruction; USD funding is simulated.','payment-service','SIMULATED FUNDING'],
 ['Compliance checks and FX / fee quote','Simulated KYC, KYB, AML and sanctions checks; review the simulated quote.','compliance-quote-service','SIMULATED'],
 ['Notional USD-to-USDC funding','Allocate existing test USDC to this payment. The treasury wallet must already be prefunded.','payment-service','SIMULATED CONVERSION'],
 ['Token balance checks and gas estimation','Check sufficient USDC and test ETH. Estimate the network fee before authorizing the transfer.','blockchain-service','TESTNET IN CONNECTED POC'],
 ['Treasury authorizes the USDC transfer','Signing cryptographically authorizes the transfer using the treasury key. Keys are never displayed.','blockchain-service','TESTNET IN CONNECTED POC'],
 ['Platform broadcasts the transfer','Submission sends the signed transaction to the testnet and records its hash. USDC moves; ETH pays gas.','blockchain-service','TESTNET IN CONNECTED POC'],
 ['Confirm blockchain settlement and post ledger','Check receipt, success and required confirmations; post balanced internal settlement entries.','blockchain-service / settlement-ledger-service','TESTNET + LEDGER'],
 ['Optional fiat payout to the supplier','Simulated USDC-to-fiat conversion, Visa payout and credit to the supplier bank account.','VisaPaymentAdapter / visa-simulator','SIMULATED / OPTIONAL'],
 ['Reconcile all records','Compare payment, ledger, blockchain evidence and optional simulated Visa payout.','reconciliation-service','DETERMINISTIC CHECKS']
];
let payment=null,sequence=0,timer=null,running=false,scenario='success',agentText='';
const cash=(n,asset='USD')=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)+' '+asset;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(s,t='')=>`<span class="badge ${t}">${esc(s)}</span>`;
const info=rows=>`<dl class="info-list">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
const card=(title,body,tag='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${tag}</div><div class="card-body">${body}</div></section>`;
const head=(title,sub,action='')=>`<div class="page-head"><div><p class="eyebrow">Treasury operations / concept experience</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${action}</div></div>`;
const btn=(label,action,kind='')=>`<button type="button" class="btn ${kind}" data-action="${action}">${label}</button>`;
const statusBadge=()=>badge(payment?.status||'NO PAYMENT',payment?.status==='RECONCILED'?'success':payment?.error?'danger':'warn');
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;document.getElementById('announcement').textContent=message;setTimeout(()=>{el.hidden=true;},4200);}
function stop(){clearTimeout(timer);timer=null;running=false;}
function emit(type,status){if(status)payment.status=status;payment.events.unshift({eventId:`EVT-DEMO-${String(payment.events.length+1).padStart(3,'0')}`,eventType:type,eventVersion:1,paymentId:payment.id,correlationId:payment.correlationId,timestamp:new Date().toISOString(),status:payment.status});}
function create(amount=10000,route='wallet',sender='Atlas Manufacturing Inc.',beneficiary='Meridian Components Ltd.',purpose='Supplier invoice INV-2026-1042'){
 stop();sequence++;payment={id:`PAY-DEMO-${String(sequence).padStart(4,'0')}`,correlationId:`CORR-DEMO-${String(sequence).padStart(4,'0')}`,idempotencyKey:`IDEM-DEMO-${sequence}`,amount,route,sender,beneficiary,purpose,index:0,status:'CREATED',quoteAccepted:false,waitingQuote:false,error:null,uncertain:false,submitted:false,submissionCount:0,confirmed:false,reconciled:false,events:[],journals:[],receiptAmount:amount,details:['USD instruction created. Funding is illustrative.'],confirmations:0};agentText='';emit('PaymentCreated');location.hash='journey';render();notify('Demo payment created. No bank account was debited.');
}
function journal(title,asset,dr,cr){payment.journals.push({id:`JRN-DEMO-${payment.journals.length+1}`,title,asset,dr,cr,amount:payment.amount});}
function tick(){
 if(!payment||!running)return;
 const p=payment,i=p.index+1;
 if(i===1){emit('ComplianceStarted','COMPLIANCE_PENDING');if(scenario==='compliance'){p.index=1;p.error='Compliance rejected by the selected simulation scenario.';p.details[1]=p.error;emit('ComplianceCompleted','COMPLIANCE_REJECTED');stop();render();return;}emit('ComplianceCompleted','COMPLIANCE_APPROVED');emit('QuotePrepared','QUOTE_PENDING');p.waitingQuote=true;p.index=1;p.details[1]='Screening passed (simulated). Quote: 1 USD = 1 USDC; fee 0.00 USD. Awaiting operator acceptance.';stop();}
 else if(i===2){emit('FundingRequested','FUNDING_PENDING');journal('Simulated USD funding','USD','110002 · Stablecoin Funding Clearing','110001 · Corporate USD Control');emit('StablecoinFundingCompleted','FUNDED');p.details[i]=`${cash(p.amount,'USDC')} allocated from prefunded test USDC. No minting or real fiat conversion.`;}
 else if(i===3){p.details[i]=`Illustrative checks: 25,000.00 USDC ≥ ${cash(p.amount,'USDC')}; 0.05 test ETH ≥ 0.00001 ETH reserved. Estimate: 65,000 gas × 0.1 gwei = 0.0000065 ETH.`;emit('WalletChecksCompleted');}
 else if(i===4){p.details[i]='Illustrative signing complete. A connected POC would use protected signing credentials. No key was requested or used here.';emit('TransferAuthorizationPrepared');}
 else if(i===5){p.submitted=true;p.submissionCount++;journal('USDC submission','USDC','120002 · USDC In Transit','120001 · USDC Treasury');if(scenario==='uncertain'){p.uncertain=true;p.details[i]='Submission outcome unknown. Inspect existing transaction evidence before any retry; never blindly rebroadcast.';p.index=i;emit('SubmissionOutcomeUnknown');stop();render();return;}emit('BlockchainTransactionSubmitted','BLOCKCHAIN_SUBMITTED');p.details[i]='Illustrative broadcast recorded once. Transaction hash is unavailable because this prototype is offline.';}
 else if(i===6){p.confirmed=true;p.confirmations=3;p.receiptAmount=scenario==='mismatch'?p.amount-25:p.amount;emit('BlockchainTransactionConfirmed','BLOCKCHAIN_CONFIRMED');journal('USDC confirmation and settlement','USDC','120003 · Beneficiary USDC Settlement','120002 · USDC In Transit');emit('SettlementCompleted','SETTLEMENT_COMPLETED');p.details[i]='Illustrative receipt SUCCESS; 3 of 3 confirmations. Internal double-entry settlement journal posted.';}
 else if(i===7){if(p.route==='fiat'){emit('VisaPayoutInitiated','VISA_PAYOUT_PENDING');emit('VisaPayoutCompleted','VISA_PAYOUT_COMPLETED');p.details[i]=`Simulated off-ramp and Visa payout ${cash(p.amount)}; supplier bank credit simulated. Reference VISA-DEMO-${sequence}.`;}else{p.details[i]='Skipped by route selection. Supplier retains test USDC; no fiat conversion, Visa payout or bank credit.';emit('OptionalPayoutSkipped');}}
 else if(i===8){emit('ReconciliationStarted','RECONCILIATION_PENDING');if(scenario==='mismatch'){p.error='Reconciliation mismatch: illustrative blockchain amount differs by 25.00 USDC.';p.details[i]=p.error;emit('ReconciliationMismatch');}else{p.reconciled=true;p.details[i]='Payment, balanced ledger and illustrative receipt match. Optional simulated Visa evidence '+(p.route==='fiat'?'matches.':'is not applicable.');emit('ReconciliationCompleted','RECONCILED');}stop();}
 p.index=i;render();if(running)timer=setTimeout(tick,1100);
}
function play(){if(!payment){create();}if(payment.error||payment.uncertain||payment.waitingQuote||payment.index>=8)return;running=true;render();timer=setTimeout(tick,700);}
function empty(){return `<div class="card empty"><div class="empty-icon">↗</div><h2>Your payment story starts here</h2><p>Create a USD 10,000 demo payment to explore the entire nine-step journey.</p>${btn('Create sample payment','sample','primary')} <a class="btn" href="#new">Enter payment details</a></div>`;}
function overview(){const p=payment;return head('Payments, with a clearer path.','A single view of treasury liquidity, stablecoin settlement and supplier outcomes.',`<a class="btn primary" href="#new">＋ Initiate payment</a>`)+`<section class="hero"><div><p class="eyebrow">CROSS-BORDER B2B PAYMENTS</p><h2>From USD instruction<br>to reconciled settlement.</h2><p>Move through nine transparent steps. Follow the USDC payment, understand ETH gas, and inspect every illustrative record.</p>${btn(p?'Continue payment journey':'Explore a USD 10,000 payment',p?'journey':'sample')}</div><div class="hero-route"><div class="route-node"><span class="coin">$</span>Customer USD<small>SIMULATED FUNDING</small></div><div class="route-arrow">→</div><div class="route-node"><span class="coin usdc">$</span>Test USDC<small>TARGET: BASE SEPOLIA</small></div><div class="route-arrow">→</div><div class="route-node"><span class="coin">↗</span>Supplier<small>WALLET / FIAT</small></div></div></section><div class="kpis"><div class="card kpi"><div class="kpi-label">Customer USD balance</div><div class="kpi-value">${cash(250000-(p?.index>=2?p.amount:0),'').trim()} <span>USD</span></div><div class="kpi-foot">Simulated customer payment account</div></div><div class="card kpi"><div class="kpi-label">Treasury test USDC</div><div class="kpi-value">${cash(25000-(p?.confirmed?p.amount:0),'').trim()} <span>USDC</span></div><div class="kpi-foot">Illustrative opening balance: 25,000</div></div><div class="card kpi"><div class="kpi-label">Treasury network fee reserve</div><div class="kpi-value">0.05 <span>test ETH</span></div><div class="kpi-foot">Illustrative opening balance · not live</div></div><div class="card kpi"><div class="kpi-label">Reconciliation</div><div class="kpi-value">${p?.reconciled?'Matched':p?.error?'Review':p?'Pending':'Ready'}</div><div class="kpi-foot">${p?'One session payment':'No payment created yet'}</div></div></div>`+`<div class="grid-two"><div class="stack"><section class="card"><div class="card-head"><h2>Current payment</h2>${p?statusBadge():badge('READY TO EXPLORE')}</div>${p?`<div class="table-wrap"><table><thead><tr><th>Payment / supplier</th><th>Amount</th><th>Route</th><th></th></tr></thead><tbody><tr><td><strong>${p.id}</strong><small>${esc(p.beneficiary)}</small></td><td>${cash(p.amount)}<small>${cash(p.amount,'USDC')} principal</small></td><td>${p.route==='fiat'?'USDC + simulated fiat':'USDC wallet'}</td><td><a href="#journey">View journey →</a></td></tr></tbody></table></div>`:`<div class="card-body"><p class="muted">No payment in this local session.</p>${btn('Create sample payment','sample','small')}</div>`}</section>${card('The nine-step payment journey',`<p class="muted tiny">USD initiation → compliance / quote → USDC allocation → balances / gas → signing → submission → confirmation / ledger → optional fiat payout → reconciliation.</p><a href="#journey">Open the detailed journey →</a>`)}</div>${card('What is real in the intended POC?',`<h3>Public testnet + application</h3><p class="tiny muted">Test USDC transfer, transaction hash, confirmations, event processing, double-entry ledger and reconciliation.</p><hr class="divider"><h3>Explicit simulations</h3><p class="tiny muted">Fiat funding, FX, conversion, compliance, Visa and supplier fiat credit.</p><div class="callout">This standalone prototype illustrates both groups. It executes no real operation.</div>`)}</div>`;}
function newPayment(){return head('Initiate a supplier payment','Prepare a USD instruction. Choose how the supplier receives the final value.')+`<form id="payment-form"><div class="grid-two"><section class="card"><div class="card-head"><h2>Payment instruction</h2>${badge('SIMULATED USD FUNDING')}</div><div class="card-body"><div class="field-grid form-section"><div class="field"><label for="sender">Customer / sender</label><input id="sender" name="sender" value="Atlas Manufacturing Inc." required maxlength="100"></div><div class="field"><label for="beneficiary">Supplier / beneficiary</label><input id="beneficiary" name="beneficiary" value="Meridian Components Ltd." required maxlength="100"></div><div class="field"><label for="amount">Payment amount (USD)</label><input id="amount" name="amount" type="number" min="0.01" max="25000" step="0.01" value="10000" required><small>Prototype liquidity limit: USD 25,000.</small></div><div class="field"><label for="currency">Source / payout currency</label><input id="currency" value="USD" readonly></div><div class="field full"><label for="purpose">Payment purpose</label><input id="purpose" name="purpose" value="Supplier invoice INV-2026-1042" required maxlength="150"></div></div><div class="form-section"><h3>Supplier delivery route</h3><div class="route-options"><label class="route-option"><input type="radio" name="route" value="wallet" checked><span>USDC wallet settlement<small>Supplier retains test USDC. Step 8 is skipped.</small></span></label><label class="route-option"><input type="radio" name="route" value="fiat"><span>USDC + simulated fiat payout<small>Simulated off-ramp, Visa and supplier bank credit.</small></span></label></div></div><div class="callout neutral">Beneficiary location: United Kingdom (fictional supplier). USD payout account is assumed; this example has no additional local-currency FX leg.</div><div class="form-footer section-gap"><span class="tiny muted">No money moves. Starting a new payment replaces this session's demo.</span><button class="btn primary" type="submit">Create demo payment →</button></div></div></section><div class="stack">${card('Quote preview',`<p class="eyebrow">ILLUSTRATIVE / NOT A MARKET RATE</p><div class="amount-preview" id="quote-amount">10,000.00 <small>test USDC principal</small></div>${info([['Notional conversion','1 USD = 1 USDC'],['Demo platform fee','0.00 USD'],['Network fee','Paid separately in test ETH'],['Customer balance','250,000.00 USD · simulated']])}<p class="tiny muted">Final demo quote is reviewed and accepted at step 2. Gas is a blockchain computation fee; no USDC-to-ETH swap occurs.</p>`)}${card('Treasury readiness',`<ul class="plain-list"><li>Prefunded test USDC wallet</li><li>Separate test ETH gas reserve</li><li>Balance and fee checks before signing</li><li>Private keys remain outside the UI</li></ul>`)}</div></div></form>`;}
function controls(){const p=payment;return `<div class="scenario-bar"><label for="scenario">Walkthrough scenario</label><select id="scenario" ${p?'disabled':''}><option value="success">Successful settlement</option><option value="compliance">Compliance rejection</option><option value="uncertain">Submission outcome unknown</option><option value="mismatch">Reconciliation amount mismatch</option></select><span class="muted">Choose before creating a payment.</span><div class="actions" style="margin-left:auto">${btn('Reset session','reset','small')}${!p?btn('Create sample','sample','primary small'):p.waitingQuote?btn('Accept simulated quote & continue','accept','primary small'):p.uncertain?btn('Inspect existing receipt','recover','primary small'):p.index<8&&!p.error?btn(running?'Pause walkthrough':'Run walkthrough',running?'pause':'play','primary small'):''}</div></div>`;}
function journey(){const p=payment;let out=head('One payment. Nine visible steps.','Follow the intended end-to-end experience. Every result here is an offline illustration.')+controls();if(!p)return out+empty();out+=`<div class="grid-two"><section class="card"><div class="card-head"><div><h2>${p.id} · ${cash(p.amount)}</h2><small>${esc(p.sender)} → ${esc(p.beneficiary)}</small></div>${statusBadge()}</div><div class="timeline">${steps.map((s,i)=>{const error=p.error&&i===p.index,current=i===p.index,done=i<p.index||i===8&&p.reconciled||i===7&&p.index>=7&&!p.waitingQuote;return `<article class="timeline-item ${error?'error':done?'done':current?'current':''}"><span class="step-dot">${done?'✓':i+1}</span><div><div class="step-head"><h3>${s[0]}</h3>${badge(i===7&&p.route==='wallet'?'SKIPPED BY ROUTE':s[3],error?'danger':i<3||i===7?'warn':'')}</div><p class="step-description">${s[1]}</p><span class="owner">${s[2]}</span>${p.details[i]?`<div class="step-detail">${esc(p.details[i])}</div>`:''}</div></article>`;}).join('')}</div></section><div class="stack">${card('Payment context',info([['Payment ID',p.id],['Correlation ID',`<span class="mono">${p.correlationId}</span>`],['Idempotency key',`<span class="mono">${p.idempotencyKey}</span>`],['Supplier delivery',p.route==='fiat'?'USDC + simulated USD payout':'USDC wallet'],['Current payment state',statusBadge()],['Walkthrough',running?'Running':p.waitingQuote?'Quote acceptance required':p.uncertain?'Evidence inspection required':p.index===8?'Finished':'Paused']])+`<div class="progress-track"><span style="width:${(p.index+1)/9*100}%"></span></div>`)}${p.waitingQuote?card('Review the simulated quote',info([['Principal',cash(p.amount)],['Notional conversion',cash(p.amount,'USDC')],['FX assumption','1 USD = 1 USDC'],['Platform fee','0.00 USD']])+`<p class="tiny muted">Test ETH pays network gas separately. No market quote was requested.</p>${btn('Accept quote & continue','accept','primary')}`):''}${card('Auditable event trail',`<p class="tiny muted">Illustrative versioned events share the same payment and correlation IDs. Newest first.</p><div class="event-list">${p.events.map(e=>`<div class="event-item"><b>${e.eventType}</b><span class="mono">${e.eventId} · v${e.eventVersion}</span><small>${e.timestamp}</small><small>${e.paymentId} / ${e.correlationId}</small><small>${e.status}</small></div>`).join('')}</div>`)}<div class="callout warn">A timeout after submission requires checking the existing transaction. Blind retries can cause duplicate payments.</div></div></div>`;return out;}
function blockchain(){const p=payment;return head('Blockchain evidence','Token balance checks, gas estimation, signing, submission and confirmation in one view.',`<a class="btn" href="#journey">View journey →</a>`)+`<div class="callout warn">OFFLINE ILLUSTRATION: no public testnet was queried. Transaction hash, contract address and block number remain unavailable. Do not treat this screen as real blockchain evidence.</div><div class="grid-equal section-gap">${card('Transfer instruction',`<div class="chain-path"><div class="wallet"><p class="eyebrow">FROM / TREASURY</p><h3>Atlas testnet wallet</h3><small>Address not connected</small></div><div class="token-path">→<small>${p?cash(p.amount,'USDC'):'USDC'}</small></div><div class="wallet"><p class="eyebrow">TO / BENEFICIARY</p><h3>${p?esc(p.beneficiary):'Meridian Components Ltd.'}</h3><small>Address not connected</small></div></div><div class="section-gap">${info([['Target network','Base Sepolia'],['Target chain ID','84532'],['Token','Circle official test USDC · configured in backend'],['Contract address','Not connected'],['Payment ID',p?.id||'No payment'],['Correlation ID',p?.correlationId||'No payment']])}</div>`)}${card('Wallet and gas checks',info([['Opening USDC balance','25,000.00 USDC · illustrative'],['Required principal',p?cash(p.amount,'USDC'):'Create a payment'],['Opening gas balance','0.05 test ETH · illustrative'],['Estimated gas units','65,000 · illustrative'],['Assumed effective gas price','0.1 gwei · illustrative'],['Estimated execution fee','0.0000065 ETH'],['Reserved fee buffer','0.00001 ETH']])+`<div class="callout section-gap">Gas measures blockchain computation. ETH pays the network fee; USDC remains the transferred asset.</div><p class="tiny muted">These fixed teaching values are not an RPC quote. A connected Base estimator must account for applicable execution and data fees and actual fee volatility.</p>`)}</div><div class="grid-equal section-gap">${card('Signing and submission',info([['Signing',p?.index>=4?'Illustrated authorization only':'Not started'],['Key access','No private key requested or stored'],['Submission attempts',String(p?.submissionCount||0)],['Transaction status',p?.uncertain?badge('SUBMISSION_UNKNOWN','warn'):p?.confirmed?badge('ILLUSTRATIVE SUCCESS','success'):p?.submitted?badge('ILLUSTRATIVE SUBMITTED'):'Not submitted'],['Transaction hash','Unavailable — offline prototype'],['Explorer','Disabled until a real hash exists']])+`<button class="btn small section-gap" disabled title="A real public testnet hash is required">View on explorer ↗</button>`)}${card('Receipt and confirmation handling',info([['Receipt evidence',p?.confirmed?'DEMO-RECEIPT-001 (not a chain hash)':'Not available'],['Receipt success',p?.confirmed?'Illustrative SUCCESS':'Not available'],['Required / observed confirmations',p?.confirmed?'3 / 3 · illustrative':'3 / 0'],['Receipt token amount',p?.confirmed?cash(p.receiptAmount,'USDC'):'Not available'],['Block number','Unavailable — no block queried'],['Actual gas used','Unavailable — no transaction executed']])+`<p class="tiny muted">The connected application must persist network, chainId, tokenContract, senderWallet, recipientWallet, tokenAmount, transactionHash, blockNumber, gasUsed and transactionStatus.</p>`)}</div>`;}
function ledger(){const p=payment,js=p?.journals||[];return head('Balanced books. Traceable settlement.','An internal double-entry ledger records financial movements independently of blockchain evidence.')+`<div class="callout">Illustrative journals use approved account codes and balance separately for each asset. Posted entries have no edit action; corrections require reversal or compensating entries.</div><div class="grid-two section-gap"><div class="stack">${js.length?js.map(j=>`<section class="card"><div class="journal-title"><div><h2>${j.title}</h2><small>${j.id} · ${p.id} · ${p.correlationId}</small></div>${badge('ILLUSTRATIVE POSTED','success')}</div><div class="table-wrap"><table><thead><tr><th>Ledger account</th><th class="right">Debit (${j.asset})</th><th class="right">Credit (${j.asset})</th></tr></thead><tbody><tr><td>${j.dr}</td><td class="right">${cash(j.amount,'')}</td><td class="right">—</td></tr><tr><td>${j.cr}</td><td class="right">—</td><td class="right">${cash(j.amount,'')}</td></tr></tbody></table></div><div class="balance-strip"><span>Debits = credits in ${j.asset}</span><strong>✓ Balanced</strong></div></section>`).join(''):empty()}</div><div class="stack">${card('Per-asset posting totals',info(['USD','USDC'].map(asset=>{const total=js.filter(j=>j.asset===asset).reduce((n,j)=>n+j.amount,0);return [asset,`${cash(total,asset)} DR<br>${cash(total,asset)} CR`];}))+`<p class="tiny muted">Totals are journal turnover, not wallet balances. USD is never offset against USDC to claim balance.</p>`)}${card('Conversion allocation memo',`<p class="tiny muted">Step 3 allocates prefunded test USDC. It does not actually acquire or mint tokens.</p><p class="tiny muted">The existing ledger document's mixed USD/USDC acquisition example conflicts with its per-asset balancing rule. This prototype therefore presents conversion as a memo, without posting an invalid journal.</p><div class="callout warn">Conversion clearing, gas, fee and payout journal mappings remain accounting design TODOs. This screen is not a complete accounting implementation.</div>`)}${card('Account ownership',`<h3>Customer payment account</h3><p class="tiny muted">payment-service owns the simulated customer USD holding.</p><h3>Chart of accounts</h3><p class="tiny muted">settlement-ledger-service owns accounting classifications and immutable journal entries, per ADR-012.</p>`)}</div></div>`;}
function reconRows(){const p=payment;if(!p)return [];return [
 ['Payment instruction',cash(p.amount),'USD',p.id,'Recorded'],
 ['Funding journal',cash(p.amount),'USD',p.journals[0]?.id||'Pending',p.index>=2?'Balanced':'Pending'],
 ['USDC settlement ledger',cash(p.amount,'USDC'),'USDC',p.confirmed?'Confirmation journal':'Pending',p.confirmed?'Balanced':'Pending'],
 ['Blockchain receipt',p.confirmed?cash(p.receiptAmount,'USDC'):'Awaiting receipt','USDC',p.confirmed?'DEMO-RECEIPT-001':'No chain hash',p.confirmed?(p.receiptAmount===p.amount?'Matched':'Mismatch'):'Pending'],
 ['Simulated Visa payout',p.route==='fiat'?cash(p.amount):'Not applicable','USD',p.route==='fiat'&&p.index>=7?`VISA-DEMO-${sequence}`:'—',p.route==='wallet'?'N/A':p.index>=7?'Matched':'Pending'],
 ['Supplier bank credit',p.route==='fiat'?cash(p.amount):'Not applicable','USD','Simulated only',p.route==='wallet'?'N/A':p.index>=7?'Matched':'Pending']
 ];}
function reconciliation(){const p=payment;return head('Reconciliation with evidence.','Match amounts, assets, states and references across all payment legs.',`<a class="btn" href="#agent">Investigate payment ✧</a>`)+(p?`<div class="kpis"><div class="card kpi"><div class="kpi-label">Final reconciliation</div><div class="kpi-value">${p.reconciled?'Matched':p.index===8?'Mismatch':'Pending'}</div><div class="kpi-foot">${p.reconciled?'Illustrative checks completed':'Only completed evidence can be matched'}</div></div><div class="card kpi"><div class="kpi-label">Payment principal</div><div class="kpi-value">${cash(p.amount,'')} <span>USD</span></div><div class="kpi-foot">Notional 1:1 USDC conversion</div></div><div class="card kpi"><div class="kpi-label">Blockchain evidence</div><div class="kpi-value">${p.confirmed?'Illustrated':'Pending'}</div><div class="kpi-foot">No real testnet receipt in this prototype</div></div><div class="card kpi"><div class="kpi-label">Optional Visa leg</div><div class="kpi-value">${p.route==='wallet'?'N/A':p.index>=7?'Simulated':'Pending'}</div><div class="kpi-foot">Supplier credit is always simulated</div></div></div><section class="card"><div class="card-head"><h2>${p.id} · reconciliation worksheet</h2>${statusBadge()}</div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Amount</th><th>Asset</th><th>Evidence reference</th><th>Check</th></tr></thead><tbody>${reconRows().map(r=>`<tr>${r.map((v,i)=>`<td>${i===4?badge(v,v==='Mismatch'?'danger':v==='Matched'||v==='Balanced'?'success':''):esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="card-body"><div class="callout ${p.index===8&&!p.reconciled?'danger':''}">${p.reconciled?'All required illustrative legs match; the payment is RECONCILED.':p.index===8?'Receipt reports '+cash(p.receiptAmount,'USDC')+' against '+cash(p.amount,'USDC')+' instructed. Keep RECONCILIATION_PENDING and investigate; no corrective payment or ledger edit is performed.':'Reconciliation awaits completed settlement and optional payout evidence. Incomplete evidence cannot establish a match.'}</div><p class="tiny muted">Common correlation ID: <span class="mono">${p.correlationId}</span>. Payment, ledger and receipt must also match network, token, recipient, amount, success and confirmation requirements in the connected implementation.</p></div></section>`:empty());}
function agent(){return head('Understand the payment story.','An advisory investigation concept, based on proposed ADR-013.',badge('PROPOSED / SCRIPTED PREVIEW','purple'))+`<div class="grid-two"><section class="card"><div class="card-body"><div class="agent-symbol">✧</div><h2>Payment Investigation Agent</h2><p class="subtitle section-gap">Ask for an explanation grounded in payment, ledger, blockchain and reconciliation records.</p><div class="callout warn section-gap">This preview uses fixed, scenario-based text. No model, inference, tool selection or agent runtime is implemented. ADR-013 remains proposed.</div><div class="actions section-gap">${btn('Explain current status','agent-status')}${btn('Inspect risk / discrepancy','agent-risk')}</div><div class="agent-answer" id="agent-answer" role="status">${esc(agentText||'Create a demo payment, then select an investigation prompt. This view will explain its illustrative evidence.')}</div><div class="evidence-links"><a class="btn small" href="#journey">Payment / events</a><a class="btn small" href="#blockchain">Blockchain evidence</a><a class="btn small" href="#ledger">Ledger journals</a><a class="btn small" href="#reconciliation">Reconciliation</a></div></div></section><div class="stack">${card('Proposed capability boundary',`<h3>Read and explain</h3><ul class="plain-list"><li>Summarize recorded payment status</li><li>Compare existing evidence</li><li>Investigate delays and discrepancies</li><li>Recommend human review when evidence is missing</li></ul><hr class="divider"><h3>Execution remains deterministic</h3><p class="tiny muted">The agent has no authority to approve compliance, sign, submit, retry a payment, trigger Visa payout or mutate posted journals. It has no private-key access.</p>`)}${card('Deployment direction',`<p class="tiny muted">If accepted and implemented, the bounded, read-only agent would run inside payment-service. Six services remain; model provider selection and evaluation are still pending.</p><a href="../adr/ADR-013-PAYMENT-INVESTIGATION-AGENT.md" class="tiny">Read proposed ADR-013 ↗</a>`)}</div></div>`;}
function platform(){const services=[['payment-service','Payment APIs, orchestration, explicit state transitions, idempotency and correlation.'],['compliance-quote-service','Simulated compliance screening, notional FX and fee quote.'],['blockchain-service','Balances, gas estimates, protected signing, submission and confirmations.'],['settlement-ledger-service','Double-entry journals, per-asset balance validation and reversals.'],['reconciliation-service','Compare payment, ledger, blockchain and optional payout records.'],['visa-simulator','Simulated payout through VisaPaymentAdapter; future VisaDirectAdapter.']];return head('Six services. One traceable payment.','Intended AWS architecture. This prototype does not indicate deployment or integration completeness.')+card('Application and infrastructure',`<div class="architecture-edge">React + TypeScript frontend → Amazon API Gateway → internal ALB → Java 21 / Spring Boot 3.x on ECS Fargate</div><div class="service-grid section-gap">${services.map(([name,desc])=>`<div class="service-card"><h3>${name}</h3><p>${desc}</p></div>`).join('')}</div><div class="architecture-edge section-gap">Amazon EventBridge → Amazon SQS + dead-letter queues<br>Aurora PostgreSQL · AWS Secrets Manager + KMS · AWS CDK + TypeScript</div><p class="tiny muted">Same correlationId across HTTP, payment, events, journals, blockchain, Visa and reconciliation. Idempotent APIs and consumers prevent duplicate effects. Failed blockchain submissions require evidence checks before retry.</p>`)+`<div class="grid-equal section-gap">${card('Prototype scope and remaining work',`<ul class="plain-list"><li>Connect the complete orchestration and event chain.</li><li>Execute and persist a genuine test USDC transfer.</li><li>Complete payout, ledger mapping and reconciliation integration.</li><li>Implement the production UI in React + TypeScript.</li><li>Complete deployment, secrets, observability and end-to-end testing.</li><li>Review ADR-013 before implementing an actual advisory agent.</li></ul>`)}${card('Architecture assumptions',`<p class="tiny muted">This user-requested standalone HTML prototype is a separate design artifact. It does not replace the required React + TypeScript application or alter the six service boundaries.</p><p class="tiny muted">Base Sepolia is the preferred target; Ethereum Sepolia is fallback. Circle official test USDC is configured per environment. Wallet addresses and token contracts are intentionally absent from the offline demo.</p><div class="callout">Fiat funding, conversion, FX, compliance, Visa and beneficiary fiat credit remain simulations in the intended POC.</div>`)}</div>`;}
function render(){const page=Object.hasOwn(pages,location.hash.slice(1))?location.hash.slice(1):'overview';document.title=`${pages[page]} | StableFlow`;document.getElementById('breadcrumb').textContent=pages[page];document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('main').innerHTML=({overview,new:newPayment,journey,blockchain,ledger,reconciliation,agent,platform}[page])();const select=document.getElementById('scenario');if(select)select.value=scenario;}
function investigate(risk){if(!payment){agentText='Evidence unavailable: no payment exists in this session. Create a demo payment to inspect its records.';render();return;}const p=payment;let finding=p.reconciled?'All required illustrative records match. No discrepancy is recorded.':p.uncertain?'Submission outcome is unknown. One illustrative submission attempt exists; the payment state remains FUNDED until evidence resolves the uncertainty.':p.index===8&&!p.reconciled?`The receipt shows ${cash(p.receiptAmount,'USDC')}, while the instruction and ledger show ${cash(p.amount,'USDC')}. The difference is 25.00 USDC. Reconciliation remains pending.`:p.error?p.error:p.waitingQuote?'Compliance passed in simulation. The payment is awaiting explicit acceptance of the simulated FX / fee quote.':'The walkthrough has not completed. Later settlement and reconciliation evidence may be unavailable.';agentText=`RECORDED FACTS\n${p.id} / ${p.correlationId}\nState: ${p.status}. ${p.journals.length} illustrative journals; ${p.submissionCount} illustrative submission attempts.\n\n${risk?'RISK / DISCREPANCY':'EXPLANATION'}\n${finding}\n\nRECOMMENDED NEXT STEP\n${p.uncertain?'Inspect the previously submitted transaction receipt; do not blindly rebroadcast.':p.error?'Have an operator review the linked evidence. Do not edit posted entries or generate another payment automatically.':p.waitingQuote?'Review and accept the quote if the illustrative terms are suitable.':p.reconciled?'Retain the correlated evidence and audit trail.':'Continue the guided walkthrough and verify each completed leg.'}\n\nLIMITATION\nScripted explanation from offline sample records. No AI inference or real external verification.`;render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case 'sample':create();break;case 'journey':location.hash='journey';break;case 'play':play();break;case 'pause':stop();render();break;case 'accept':if(!payment?.waitingQuote)return;payment.waitingQuote=false;payment.quoteAccepted=true;emit('QuoteAccepted','QUOTE_ACCEPTED');emit('RailSelected','RAIL_SELECTED');payment.details[1]='Simulated screening passed; quote accepted. 1 USD = 1 USDC, zero platform fee. Stablecoin rail selected.';play();break;case 'recover':if(!payment?.uncertain)return;payment.uncertain=false;emit('ExistingSubmissionEvidenceRecovered','BLOCKCHAIN_SUBMITTED');payment.details[5]='Illustrative inspection located the existing submission. Continuing with receipt monitoring; no rebroadcast. Submission count remains 1.';play();break;case 'reset':stop();payment=null;agentText='';render();notify('Session reset. Select a scenario before creating the next payment.');break;case 'agent-status':investigate(false);break;case 'agent-risk':investigate(true);break;}});
document.addEventListener('change',e=>{if(e.target.id==='scenario'&&!payment)scenario=e.target.value;});
document.addEventListener('input',e=>{if(e.target.id==='amount'){const n=Number(e.target.value);document.getElementById('quote-amount').innerHTML=`${Number.isFinite(n)?cash(n,''): '—'} <small>test USDC principal</small>`;}});
document.addEventListener('submit',e=>{if(e.target.id!=='payment-form')return;e.preventDefault();const data=new FormData(e.target),amount=Number(data.get('amount')),sender=String(data.get('sender')).trim(),beneficiary=String(data.get('beneficiary')).trim(),purpose=String(data.get('purpose')).trim();if(!Number.isFinite(amount)||amount<=0||amount>25000||Math.abs(amount*100-Math.round(amount*100))>0.000001||!sender||!beneficiary||!purpose){notify('Enter valid names, purpose and an amount from 0.01 to 25,000 USD with at most two decimal places.');return;}create(amount,data.get('route'),sender,beneficiary,purpose);});
window.addEventListener('hashchange',()=>{render();document.getElementById('main').focus({preventScroll:true});window.scrollTo(0,0);});
render();
